package com.medicinemanager.service;
import com.medicinemanager.dto.Requests.UserRequest; import com.medicinemanager.entity.AppUser; import com.medicinemanager.exception.*; import com.medicinemanager.repository.AppUserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class UserService { private final AppUserRepository repo; private final PasswordEncoder encoder; public UserService(AppUserRepository r,PasswordEncoder e){repo=r;encoder=e;} public List<AppUser> findAll(){return repo.findAll();} public AppUser find(UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("User not found"));} public AppUser create(UserRequest r){if(repo.existsByEmailIgnoreCase(r.email()))throw new ConflictException("Email is already registered");return repo.save(new AppUser(r.name().trim(),r.email().trim().toLowerCase(),encoder.encode(r.password())));} public AppUser update(UUID id,UserRequest r){var x=find(id);if(repo.existsByEmailIgnoreCaseAndIdNot(r.email(),id))throw new ConflictException("Email is already registered");x.setName(r.name().trim());x.setEmail(r.email().trim().toLowerCase());x.setPasswordHash(encoder.encode(r.password()));return repo.save(x);} public void delete(UUID id){repo.delete(find(id));}}
